61	// looksLikeULID reports whether s has the shape of a ULID: 26 characters drawn
62	// from Crockford base32 (digits plus uppercase letters, excluding I, L, O, U).
63	// The check is shape-only and case-insensitive on the alphabet; it never hits
64	// the network. A name that happened to be 26 valid base32 characters would be
65	// misread as an id, but real org/project names don't take that form, and the
66	// user can always fall back to the explicit ULID.
67	func looksLikeULID(s string) bool {
68		if len(s) != 26 {
69			return false
70		}
71		for _, r := range strings.ToUpper(s) {
72			switch {
73			case r >= '0' && r <= '9':
74			case r >= 'A' && r <= 'Z' && r != 'I' && r != 'L' && r != 'O' && r != 'U':
75			default:
76				return false
77			}
78		}
79		return true
80	}
