111	// resolveAccountRef turns an account reference into its ULID. A ULID passes
112	// through unchanged; otherwise the ref is a provider-qualified handle (e.g.
113	// "github:alice") resolved via the control plane. We support github-backed
114	// user accounts today; other providers will resolve once they exist server-side.
115	func resolveAccountRef(ctx context.Context, c *coreapi.Client, ref string) (string, error) {
116		if looksLikeULID(ref) {
117			return ref, nil
118		}
119		provider, handle, err := parseQualifiedHandle(ref)
120		if err != nil {
121			return "", err
122		}
123		id, err := c.ResolveHandle(ctx, coreapi.ResolveHandleParams{Provider: provider, Handle: handle})
124		if err != nil {
125			return "", err
126		}
127		// ResolvedIdentity.AccountId is a plain string, so a handle that resolves to
128		// an identity with no backing account would silently forward "" as the owner
129		// ULID and fail later with an opaque server-side create error. Catch it here.
130		if id.AccountId == "" {
131			return "", fmt.Errorf("handle %q resolved to no account", ref)
132		}
133		return id.AccountId, nil
134	}
