136	// resolveGranteeProvider turns a grantee reference into the (provider,
137	// providerUserId) pair the grant/membership "by provider" routes key on. The
138	// reference is a provider-qualified handle (e.g. "github:alice"); it is
139	// resolved through the control plane to the provider's stable numeric user id.
140	// The friendly handle alone is not what the grant routes accept — passing it as
141	// --provider-user-id was the COR-699 footgun ("provider identity not found") —
142	// so the CLI always resolves it first. A bare account ULID is rejected here:
143	// the by-provider routes can't be addressed by ULID, and there is no reverse
144	// account→provider-id lookup; callers that accept a ULID grantee (project/repo
145	// remove) handle it via the typed-id route before reaching this helper.
146	func resolveGranteeProvider(ctx context.Context, c *coreapi.Client, ref string) (provider, providerUserID string, err error) {
147		// A ULID is a tempting paste from `grant … list` (which prints the grantee
148		// ID), but the by-provider routes can't be addressed by ULID. Reject it with
149		// a message that points at the form this command actually wants, rather than
150		// letting parseQualifiedHandle dangle a "(or a ULID)" hint that doesn't apply.
151		if looksLikeULID(ref) {
152			return "", "", fmt.Errorf("grantee %q is an account ULID; this command needs a provider-qualified handle like \"github:alice\"", ref)
153		}
154		p, handle, err := parseQualifiedHandle(ref)
155		if err != nil {
156			return "", "", err
157		}
158		id, err := c.ResolveHandle(ctx, coreapi.ResolveHandleParams{Provider: p, Handle: handle})
159		if err != nil {
160			if isCoreNotFound(err) {
161				return "", "", fmt.Errorf("no %s identity for handle %q", p, handle)
162			}
163			return "", "", err
164		}
165		if id.ProviderUserId == "" {
166			return "", "", fmt.Errorf("handle %q resolved to no provider user id", ref)
167		}
168		// Prefer the server-normalized provider over the raw prefix, falling back to
169		// the input when the response omits it.
170		if id.Provider != "" {
171			p = id.Provider
172		}
173		return p, id.ProviderUserId, nil
174	}
