176	// parseQualifiedHandle splits a provider-qualified handle like "github:alice"
177	// into its provider ("github") and handle ("alice"). Accounts are addressed by
178	// this friendly form; a value with no "provider:" prefix is rejected so the
179	// user gets a clear hint rather than a confusing lookup miss.
180	func parseQualifiedHandle(ref string) (provider, handle string, err error) {
181		provider, handle, ok := strings.Cut(ref, ":")
182		if !ok || provider == "" || handle == "" {
183			return "", "", fmt.Errorf("account %q must be a qualified handle like \"github:alice\" (or a ULID)", ref)
184		}
185		return provider, handle, nil
186	}
